// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(nonOwner != address(0));
        amount = bound(amount, 1, address(this).balance);
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok = true;
        try c.sendMoney(address(0xdead), amount) { ok = false; } catch { ok = true; }
        assertTrue(ok);
    }
}
